3	import org.mockito.Mockito;
4	import org.springframework.beans.factory.annotation.Autowired;
5	import org.springframework.context.ApplicationContext;
6	import org.springframework.context.ApplicationEvent;
7	import org.springframework.context.ApplicationEventPublisher;
8	import org.springframework.context.PayloadApplicationEvent;
9	import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
10	import org.springframework.context.event.EventListener;
11	import org.springframework.core.type.filter.AnnotationTypeFilter;
12	import org.springframework.stereotype.Component;
13	import org.springframework.transaction.event.TransactionalEventListener;
14	
15	import java.lang.reflect.Constructor;
16	import java.lang.reflect.Field;
17	import java.lang.reflect.InvocationTargetException;
18	import java.lang.reflect.Method;
19	import java.lang.reflect.Modifier;
20	import java.util.ArrayList;
21	import java.util.Comparator;
22	import java.util.HashMap;
23	import java.util.HashSet;
24	import java.util.List;
25	import java.util.Map;
26	import java.util.Set;
27	
28	/**
29	 * 테스트용 객체 조립기.
30	 *
31	 * - 리포지토리·EntityManager 등 테스트 컨텍스트(@DataJpaTest)에 있는 빈은 그대로 쓴다.
32	 * - com.fream.back.domain 아래의 @Service/@Component 클래스는 실제 객체로 생성자 주입해 만든다.
33	 * - 그 밖의 의존(외부 연동·Redis·WebSocket 등)은 Mockito mock으로 채운다.
34	 * - ApplicationEventPublisher로 발행한 이벤트는 domain 아래 @EventListener/@TransactionalEventListener 메서드로 즉시 전달한다.
35	 */
36	final class Wiring {
37	
38	    private static final String DOMAIN = "com.fream.back.domain";
39	
40	    private final ApplicationContext ctx;
41	    private final Map<Class<?>, Object> instances = new HashMap<>();
42	    private final Set<Class<?>> building = new HashSet<>();
43	    private List<Class<?>> listenerClasses;
44	
45	    Wiring(ApplicationContext ctx) {
46	        this.ctx = ctx;
47	        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
48	    }
49	
50	    <T> Wiring with(Class<T> type, T instance) {
51	        instances.put(type, instance);
52	        return this;
53	    }
54	
55	    @SuppressWarnings("unchecked")
56	    <T> T get(Class<T> type) {
57	        Object existing = instances.get(type);
58	        if (existing != null) {
59	            return (T) existing;
60	        }
61	        if (type == String.class) {
62	            return (T) "";
63	        }
64	        if (type.isPrimitive()) {
65	            return (T) defaultPrimitive(type);
66	        }
67	        Object bean = ctx.getBeanProvider(type).getIfUnique();
68	        if (bean != null) {
69	            return (T) bean;
70	        }
71	        Object created;
72	        if (isDomainComponent(type) && !building.contains(type)) {
73	            building.add(type);
74	            try {
75	                created = construct(type);
76	            } finally {
77	                building.remove(type);
78	            }
79	        } else {
80	            created = Mockito.mock(type);
81	        }
82	        instances.put(type, created);
83	        return (T) created;
84	    }
85	
86	    private static boolean isDomainComponent(Class<?> t) {
87	        return t.getName().startsWith(DOMAIN + ".")
88	                && !t.isInterface()
89	                && !Modifier.isAbstract(t.getModifiers())
90	                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
91	    }
92	
93	    private Object construct(Class<?> type) {
94	        try {
95	            Constructor<?> ctor = null;
96	            for (Constructor<?> c : type.getDeclaredConstructors()) {
97	                if (c.isAnnotationPresent(Autowired.class)) {
98	                    ctor = c;
99	                }
100	            }
101	            if (ctor == null) {
102	                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
103	                        .max(Comparator.comparingInt(Constructor::getParameterCount))
104	                        .orElseThrow();
105	            }
106	            Class<?>[] params = ctor.getParameterTypes();
107	            Object[] args = new Object[params.length];
108	            for (int i = 0; i < params.length; i++) {
109	                args[i] = get(params[i]);
110	            }
